WITH Base AS (SELECT * FROM transactions WHERE account_id = 3 AND account_id IN (1, 8, 12) AND txn_type IN ('DEBIT', 'CREDIT')), txn_type_summary AS (SELECT txn_type, TO_DATE(txn_time) AS txn_day, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, MIN(amount) AS min_amount FROM Base GROUP BY txn_type, TO_DATE(txn_time)) SELECT * FROM txn_type_summary WHERE min_amount > 3600 ORDER BY txn_type;
